// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public {
        c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this));
    }

    function testFuzz_property(address ward, address caller) public {
        vm.assume(ward != caller);
        vm.assume(caller != address(0));

        vm.prank(address(this));
        c.rely(ward);

        Proxy proxy = new Proxy(c);

        vm.prank(ward);
        bool ok;
        try proxy.forward() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Proxy {
    LiquidityPool immutable c;
    constructor(LiquidityPool _c) {
        c = _c;
    }
    function forward() external {
        c.updatePrice(1);
    }
}
